        // Ownable: address owner (slot 0)
        // Pausable: bool paused (slot 1)
        // StandardToken: string name (slot 2), string symbol (slot 3), 
        // uint8 decimals (part of slot 4?), uint256 totalSupply (slot 4 or 5)
        // mapping allowance (slot 5 or 6), mapping balanceOf (slot 6 or 7)

        // Let's try slot 6 for balanceOf mapping
        uint256 balanceOfMappingSlot = 6;

        // Compute storage slot for balanceOf[victim]
        // slot = keccak256(abi.encode(victim, balanceOfMappingSlot))
        bytes32 victimBalanceSlot = keccak256(abi.encode(victim, balanceOfMappingSlot));

